/// Result codes. Entry points return these as `int`.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IhsWlResult {
    Ok = 0,
    /// Null or malformed arguments, or a bad `struct_size`.
    ErrInvalid = -1,
    /// `ihs_wl_start` while running (e.g. after a hot restart). The server
    /// and its clients carry on; re-created views rebind to their toplevels.
    ErrAlreadyRunning = -2,
    ErrNotRunning = -3,
    /// Socket bind or other OS failure.
    ErrIo = -4,
    /// Internal failure, including a caught panic.
    ErrInternal = -5,
    /// Not implemented in this build.
    ErrUnsupported = -6,
    /// The output buffer is too small.
    ErrTooSmall = -7,
}

/// What `ihs_wl_pointer` returns when the client hid the cursor.
pub const IHS_WL_CURSOR_HIDDEN: c_int = 0x10000;

/// Start-up configuration.
#[repr(C)]
pub struct IhsWlConfig {
    /// `sizeof(IhsWlConfig)`.
    pub struct_size: usize,
    /// Socket name under `$XDG_RUNTIME_DIR`. NULL = auto: `wayland-ihs-N` when
    /// this process is itself a Wayland client, else `wayland-N`.
    pub socket_name: *const c_char,
}

/// What happened to a view, as posted to the event port
/// (`ihs_wl_set_event_port`) in a list `[event, view_id]`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IhsWlViewEvent {
    /// The view shows a toplevel now.
    Bound = 1,
    /// Its toplevel went away (the client closed it or disconnected); the
    /// view shows nothing until another binds.
    Closed = 2,
    /// The client asked to be maximized (its maximize button, a title bar
    /// double-click). The toplevel stays the view's size; the app decides
    /// what the view does.
    MaximizeRequested = 3,
    /// The client asked to leave maximized (restore).
    UnmaximizeRequested = 4,
    /// The client asked to be minimized.
    MinimizeRequested = 5,
    /// The client asked for fullscreen.
    FullscreenRequested = 6,
    /// The client asked to leave fullscreen.
    UnfullscreenRequested = 7,
}

/// Window events, posted to the event port as `[event, toplevel_id]`. A
/// window is a toplevel without a parent; dialogs are not posted. Values do
/// not overlap `IhsWlViewEvent`'s.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IhsWlToplevelEvent {
    /// A window mapped, or a dialog lost its parent.
    Mapped = 256,
    /// Its app_id, title or the view showing it changed.
    Changed = 257,
    /// It closed, or became a dialog.
    Unmapped = 258,
    /// Its client asks for it to be shown, with a token the focused client
    /// made for user input and still has focus.
    ActivationRequested = 259,
    /// Its client asks for it to be shown, with any other token.
    AttentionRequested = 260,
}

/// Window-state changes the app handles for a view, as bits of
/// `ihs_wl_view_capabilities`. Its client shows the buttons for these (and
/// only these: xdg-shell `wm_capabilities`), and its requests for others are
/// ignored.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IhsWlCapability {
    /// Maximize and restore.
    Maximize = 1,
    Minimize = 2,
    /// Fullscreen and back.
    Fullscreen = 4,
}

/// Every `IhsWlCapability` bit.
pub(crate) const CAPABILITY_ALL: u32 = IhsWlCapability::Maximize as u32
    | IhsWlCapability::Minimize as u32
    | IhsWlCapability::Fullscreen as u32;

/// Window states the app grants a view's toplevel, as bits of
/// `ihs_wl_view_state`: the client is told it is maximized or fullscreen
/// (and draws itself so, a fullscreen GTK window without its header bar).
/// Neither by default: the toplevel is a tile the size of its view.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IhsWlWindowState {
    Maximized = 1,
    Fullscreen = 2,
}

/// Every `IhsWlWindowState` bit.
pub(crate) const WINDOW_STATE_ALL: u32 =
    IhsWlWindowState::Maximized as u32 | IhsWlWindowState::Fullscreen as u32;

/// `IhsWlPointerEvent::kind`.
#[repr(u32)]
pub enum IhsWlPointerKind {
    Enter = 0,
    Leave = 1,
    Motion = 2,
    Button = 3,
    Axis = 4,
}

/// Pointer input, in view-local logical pixels.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct IhsWlPointerEvent {
    pub struct_size: usize,
    /// `IhsWlPointerKind`.
    pub kind: u32,
    /// Linux `BTN_*` code, for `Button`.
    pub button: u32,
    pub x: f64,
    pub y: f64,
    /// 1 = pressed, for `Button`.
    pub pressed: u32,
    /// `wl_pointer.axis_source`, for `Axis`.
    pub axis_source: u32,
    /// Scroll distance in logical px, for `Axis`.
    pub axis_x: f64,
    pub axis_y: f64,
    /// High-resolution wheel steps (120 = one detent); 0 when not a wheel.
    pub value120_x: i32,
    pub value120_y: i32,
    pub time_us: u64,
}

/// `IhsWlTouchEvent::kind`.
#[repr(u32)]
pub enum IhsWlTouchKind {
    Down = 0,
    Up = 1,
    Motion = 2,
    Cancel = 3,
    /// End of a batch of touch events.
    Frame = 4,
}

/// Touch input, in view-local logical pixels.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct IhsWlTouchEvent {
    pub struct_size: usize,
    /// `IhsWlTouchKind`.
    pub kind: u32,
    /// Contact id (Flutter's `PointerEvent.pointer`).
    pub slot: i32,
    pub x: f64,
    pub y: f64,
    pub time_us: u64,
}

/// Who a view's client is, as `ihs_wl_view_client` reports it. Strings
/// are NUL-terminated; an unset one is empty.
#[repr(C)]
pub struct IhsWlClientInfo {
    /// `sizeof(IhsWlClientInfo)`.
    pub struct_size: usize,
    /// The client's credentials (`SO_PEERCRED`) as of when it connected.
    pub pid: i32,
    pub uid: u32,
    pub gid: u32,
    /// Connected through a sandbox engine's security context
    /// (wp_security_context_v1). The fields below are the engine's, which
    /// the client cannot set; empty otherwise.
    pub sandboxed: bool,
    /// The sandbox engine, e.g. `org.flatpak`.
    pub sandbox_engine: [c_char; 256],
    /// The app within the sandbox engine, e.g. a flatpak app id.
    pub sandbox_app_id: [c_char; 256],
    /// The running instance of the app.
    pub sandbox_instance_id: [c_char; 256],
    /// From the client's `/.flatpak-info`, with or without a security
    /// context; empty outside flatpak. A client outside any sandbox can
    /// stage its own, so only `sandboxed` vouches for it.
    pub flatpak_app_id: [c_char; 256],
    pub flatpak_instance_id: [c_char; 256],
}

/// A window, as `ihs_wl_toplevel_info` reports it. Strings are
/// NUL-terminated; an unset one is empty.
#[repr(C)]
pub struct IhsWlToplevelInfo {
    /// `sizeof(IhsWlToplevelInfo)`.
    pub struct_size: usize,
    /// The view showing it, or -1 while none does.
    pub view_id: i32,
    /// As the client set them; truncated to fit.
    pub app_id: [c_char; 256],
    pub title: [c_char; 256],
    /// Its client, as in `IhsWlClientInfo`.
    pub pid: i32,
    pub uid: u32,
    pub gid: u32,
    pub sandboxed: bool,
    pub sandbox_engine: [c_char; 256],
    pub sandbox_app_id: [c_char; 256],
    pub sandbox_instance_id: [c_char; 256],
    pub flatpak_app_id: [c_char; 256],
    pub flatpak_instance_id: [c_char; 256],
}

/// A window.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ToplevelInfo {
    /// The view showing it.
    pub view: Option<i32>,
    pub app_id: String,
    pub title: String,
    pub client: ClientInfo,
}

/// Who a view's client is.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ClientInfo {
    pub pid: i32,
    pub uid: u32,
    pub gid: u32,
    /// Set when it connected through a security context.
    pub sandbox: Option<Sandbox>,
    /// From the client's `/.flatpak-info`.
    pub flatpak: Option<FlatpakApp>,
}

/// A flatpak app, as its sandbox's `/.flatpak-info` names it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FlatpakApp {
    pub app_id: String,
    pub instance_id: Option<String>,
}

/// The security context a client connected through, as its sandbox engine
/// set it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Sandbox {
    pub engine: Option<String>,
    pub app_id: Option<String>,
    pub instance_id: Option<String>,
}

thread_local! {
    static LAST_ERROR: RefCell<CString> = RefCell::new(CString::default());
}

fn set_last_error(message: &str) {
    let message = CString::new(message.replace('\0', "")).unwrap();
    LAST_ERROR.with(|e| *e.borrow_mut() = message);
}

pub(crate) fn panic_message(payload: &(dyn Any + Send)) -> String {
    payload
        .downcast_ref::<&str>()
        .map(|s| s.to_string())
        .or_else(|| payload.downcast_ref::<String>().cloned())
        .unwrap_or_else(|| "unknown panic".into())
}

/// Run `f` as an FFI entry point: map errors to codes, record the message,
/// and turn a panic into `IhsWlResult::ErrInternal as c_int`.
fn guard(name: &str, f: impl FnOnce() -> Result<c_int>) -> c_int {
    match panic::catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(rc)) => rc,
        Ok(Err(e)) => {
            // Neither is worth a line per call: a hot restart starts again,
            // and a view may send input after a stop.
            if e.code != IhsWlResult::ErrAlreadyRunning as c_int
                && e.code != IhsWlResult::ErrNotRunning as c_int
            {
                tracing::warn!("{name}: {}", e.message);
            }
            set_last_error(&e.message);
            e.code
        }
        Err(payload) => {
            let message = format!("{name}: panic: {}", panic_message(&*payload));
            tracing::error!("{message}");
            set_last_error(&message);
            IhsWlResult::ErrInternal as c_int
        }
    }
}

/// Read a `struct_size`-first argument, rejecting NULL or a short struct.
unsafe fn sized<'a, T>(name: &str, p: *const T) -> Result<&'a T> {
    if p.is_null() {
        return Err(Error::invalid(format!("{name} is NULL")));
    }
    let size = *(p as *const usize);
    if size < std::mem::size_of::<T>() {
        return Err(Error::invalid(format!(
            "{name}: struct_size {size} < {}",
            std::mem::size_of::<T>()
        )));
    }
    Ok(&*p)
}

unsafe fn parse_config(cfg: *const IhsWlConfig) -> Result<Config> {
    let cfg = sized("config", cfg)?;
    let socket_name = if cfg.socket_name.is_null() {
        None
    } else {
        let name = CStr::from_ptr(cfg.socket_name)
            .to_str()
            .map_err(|_| Error::invalid("socket_name is not UTF-8"))?;
        if name.is_empty() || name.contains('/') {
            return Err(Error::invalid(format!("bad socket_name {name:?}")));
        }
        Some(name.to_owned())
    };
    Ok(Config { socket_name })
}

/// Start the server: spawn the compositor thread, bind the socket and
/// register the `ihs_wl/toplevel` platform-view factory. Returns once the
/// socket is listening, or with the error that stopped it.
///
/// # Safety
/// `cfg` must point to a readable `IhsWlConfig` whose strings are
/// NUL-terminated for the duration of the call.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_start(cfg: *const IhsWlConfig) -> c_int {
    guard("ihs_wl_start", || {
        thread::start(parse_config(cfg)?)?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// Stop the server: unregister the factory, disconnect every client, remove
/// the socket and join the compositor thread. A no-op when not running.
#[no_mangle]
pub extern "C" fn ihs_wl_stop() {
    guard("ihs_wl_stop", || match thread::stop() {
        Err(e) if e.code == IhsWlResult::ErrNotRunning as c_int => Ok(IhsWlResult::Ok as c_int),
        r => r.map(|()| IhsWlResult::Ok as c_int),
    });
}

/// The bound socket name (e.g. `wayland-ihs-0`), or NULL when not running.
/// Valid until `ihs_wl_stop`.
#[no_mangle]
pub extern "C" fn ihs_wl_socket_name() -> *const c_char {
    panic::catch_unwind(thread::socket_name_ptr).unwrap_or(std::ptr::null())
}

/// Issue an xdg-activation token for a client about to be launched:
/// the launcher exports it as `XDG_ACTIVATION_TOKEN` and passes the same
/// token in the view's creationParams. Writes a NUL-terminated token of at
/// most `cap` bytes to `out`; returns its length. Waits for the server
/// thread, so not from a callback the server makes.
///
/// # Safety
/// `out` must be writable for `cap` bytes.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_activation_token(out: *mut c_char, cap: usize) -> c_int {
    guard("ihs_wl_activation_token", || {
        if out.is_null() {
            return Err(Error::invalid("out is null"));
        }
        let (tx, rx) = std::sync::mpsc::sync_channel(1);
        thread::send(thread::Cmd::IssueToken(tx))?;
        let token = rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .map_err(|e| Error::new(IhsWlResult::ErrInternal as i32, format!("no token: {e}")))?;
        if token.len() >= cap {
            return Err(Error::new(
                IhsWlResult::ErrTooSmall as i32,
                format!("token needs {} bytes", token.len() + 1),
            ));
        }
        std::ptr::copy_nonoverlapping(token.as_ptr(), out.cast::<u8>(), token.len());
        *out.add(token.len()) = 0;
        Ok(token.len() as c_int)
    })
}

/// Who the client of the toplevel the view `view_id` shows is: writes
/// `info` and returns 1, or returns 0 while the view shows none. Waits for
/// the server thread, so not from a callback the server makes.
///
/// # Safety
/// `info` must point to a writable `IhsWlClientInfo` whose `struct_size` is
/// set: at least the size 0.1.0 had, which leaves the flatpak fields out.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_view_client(view_id: i32, info: *mut IhsWlClientInfo) -> c_int {
    guard("ihs_wl_view_client", || {
        const V0_1: usize = std::mem::offset_of!(IhsWlClientInfo, flatpak_app_id);
        if info.is_null() {
            return Err(Error::invalid("info is NULL"));
        }
        let size = *(info as *const usize);
        if size < V0_1 {
            return Err(Error::invalid(format!("info: struct_size {size} < {V0_1}")));
        }
        let Some(client) = view_client(view_id)? else {
            return Ok(0);
        };
        // Field by field: the caller's struct may end before the flatpak ones.
        std::ptr::addr_of_mut!((*info).pid).write(client.pid);
        std::ptr::addr_of_mut!((*info).uid).write(client.uid);
        std::ptr::addr_of_mut!((*info).gid).write(client.gid);
        std::ptr::addr_of_mut!((*info).sandboxed).write(client.sandbox.is_some());
        copy_sandbox(
            client.sandbox,
            &mut *std::ptr::addr_of_mut!((*info).sandbox_engine),
            &mut *std::ptr::addr_of_mut!((*info).sandbox_app_id),
            &mut *std::ptr::addr_of_mut!((*info).sandbox_instance_id),
        );
        if size >= std::mem::size_of::<IhsWlClientInfo>() {
            copy_flatpak(
                client.flatpak,
                &mut *std::ptr::addr_of_mut!((*info).flatpak_app_id),
                &mut *std::ptr::addr_of_mut!((*info).flatpak_instance_id),
            );
        }
        Ok(1)
    })
}

/// Writes `info` for the window `toplevel_id` and returns 1, or returns 0
/// once it is gone. Waits for the server thread.
///
/// # Safety
/// `info` must point to a writable `IhsWlToplevelInfo` whose `struct_size`
/// is set.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_toplevel_info(
    toplevel_id: i64,
    info: *mut IhsWlToplevelInfo,
) -> c_int {
    guard("ihs_wl_toplevel_info", || {
        sized("info", info.cast_const())?;
        let Some(toplevel) = toplevel_info(toplevel_id)? else {
            return Ok(0);
        };
        let info = &mut *info;
        info.view_id = toplevel.view.unwrap_or(-1);
        copy_str(&mut info.app_id, Some(&toplevel.app_id));
        copy_str(&mut info.title, Some(&toplevel.title));
        info.pid = toplevel.client.pid;
        info.uid = toplevel.client.uid;
        info.gid = toplevel.client.gid;
        info.sandboxed = toplevel.client.sandbox.is_some();
        copy_sandbox(
            toplevel.client.sandbox,
            &mut info.sandbox_engine,
            &mut info.sandbox_app_id,
            &mut info.sandbox_instance_id,
        );
        copy_flatpak(
            toplevel.client.flatpak,
            &mut info.flatpak_app_id,
            &mut info.flatpak_instance_id,
        );
        Ok(1)
    })
}

/// Writes up to `cap` window ids, oldest first, to `out` and returns how
/// many windows there are. Waits for the server thread.
///
/// # Safety
/// `out` must be writable for `cap` ids; it may be NULL when `cap` is 0.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_toplevels(out: *mut i64, cap: usize) -> c_int {
    guard("ihs_wl_toplevels", || {
        if out.is_null() && cap > 0 {
            return Err(Error::invalid("out is null"));
        }
        let ids = toplevels()?;
        for (i, id) in ids.iter().take(cap).enumerate() {
            *out.add(i) = *id;
        }
        Ok(ids.len() as c_int)
    })
}

/// Copy @p sandbox's fields, or empty ones without it.
fn copy_sandbox(
    sandbox: Option<Sandbox>,
    engine: &mut [c_char; 256],
    app_id: &mut [c_char; 256],
    instance_id: &mut [c_char; 256],
) {
    let sandbox = sandbox.unwrap_or(Sandbox {
        engine: None,
        app_id: None,
        instance_id: None,
    });
    copy_str(engine, sandbox.engine.as_deref());
    copy_str(app_id, sandbox.app_id.as_deref());
    copy_str(instance_id, sandbox.instance_id.as_deref());
}

/// Copy @p flatpak's fields, or empty ones without it.
fn copy_flatpak(
    flatpak: Option<FlatpakApp>,
    app_id: &mut [c_char; 256],
    instance_id: &mut [c_char; 256],
) {
    copy_str(app_id, flatpak.as_ref().map(|f| f.app_id.as_str()));
    copy_str(
        instance_id,
        flatpak.as_ref().and_then(|f| f.instance_id.as_deref()),
    );
}

/// Copy @p s into @p out NUL-terminated, cut at a character boundary.
fn copy_str(out: &mut [c_char; 256], s: Option<&str>) {
    let s = s.unwrap_or_default();
    let mut n = s.len().min(out.len() - 1);
    while !s.is_char_boundary(n) {
        n -= 1;
    }
    for (o, b) in out.iter_mut().zip(&s.as_bytes()[..n]) {
        *o = *b as c_char;
    }
    out[n] = 0;
}

/// Pointer input for the view `view_id`. Any thread; only enqueues. Returns
/// the cursor the client under the pointer asked for, as of the events
/// handled so far: a `wp_cursor_shape_device_v1.shape` (the default, 1, for
/// a cursor surface of its own), `IHS_WL_CURSOR_HIDDEN`, 0 before any
/// client asked -- or a negative error.
///
/// # Safety
/// `ev` must point to a readable `IhsWlPointerEvent`.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_pointer(view_id: i32, ev: *const IhsWlPointerEvent) -> c_int {
    guard("ihs_wl_pointer", || {
        let event = *sized("event", ev)?;
        if event.kind > IhsWlPointerKind::Axis as u32 {
            return Err(Error::invalid(format!("bad pointer kind {}", event.kind)));
        }
        if ![event.x, event.y, event.axis_x, event.axis_y]
            .iter()
            .all(|v| v.is_finite())
        {
            return Err(Error::invalid("pointer event is not finite"));
        }
        thread::send(thread::Cmd::Pointer { view_id, event })?;
        Ok(cursor::current())
    })
}

/// Touch input for the view `view_id`. Any thread; only enqueues.
///
/// # Safety
/// `ev` must point to a readable `IhsWlTouchEvent`.
#[no_mangle]
pub unsafe extern "C" fn ihs_wl_touch(view_id: i32, ev: *const IhsWlTouchEvent) -> c_int {
    guard("ihs_wl_touch", || {
        let event = *sized("event", ev)?;
        if event.kind > IhsWlTouchKind::Frame as u32 {
            return Err(Error::invalid(format!("bad touch kind {}", event.kind)));
        }
        if event.slot < 0 || !event.x.is_finite() || !event.y.is_finite() {
            return Err(Error::invalid("bad touch slot or position"));
        }
        thread::send(thread::Cmd::Touch { view_id, event })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// A key press (`pressed` = 1) or release for the view `view_id`, as an evdev
/// code. Any thread; only enqueues. Goes to the client only while the view
/// has keyboard focus.
#[no_mangle]
pub extern "C" fn ihs_wl_key(view_id: i32, evdev: u32, pressed: u32, time_us: u64) -> c_int {
    guard("ihs_wl_key", || {
        if evdev > input::KEY_MAX {
            return Err(Error::invalid(format!("bad evdev code {evdev}")));
        }
        thread::send(thread::Cmd::Key {
            view_id,
            evdev,
            pressed: pressed != 0,
            time_us,
        })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// Give (`focused` = 1) or take keyboard focus for the view `view_id`. Any
/// thread; only enqueues. Taking it from a view that does not have it is a
/// no-op.
#[no_mangle]
pub extern "C" fn ihs_wl_focus(view_id: i32, focused: u32) -> c_int {
    guard("ihs_wl_focus", || {
        thread::send(thread::Cmd::Focus {
            view_id,
            focused: focused != 0,
        })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// Ask the client of the toplevel the view `view_id` shows to close it
/// (`xdg_toplevel.close`). The client decides: it may ask its user first, or
/// refuse. When it closes, `IHS_WL_VIEW_EVENT_CLOSED` is posted. Any thread;
/// only enqueues. A view showing nothing is left alone.
#[no_mangle]
pub extern "C" fn ihs_wl_view_close(view_id: i32) -> c_int {
    guard("ihs_wl_view_close", || {
        thread::send(thread::Cmd::ViewClose(view_id))?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// The window-state changes the app handles for the view `view_id`, as
/// `IhsWlCapability` bits: its client shows buttons for these and no others,
/// and its requests for others are not posted. None by default. Any thread;
/// only enqueues.
#[no_mangle]
pub extern "C" fn ihs_wl_view_capabilities(view_id: i32, capabilities: u32) -> c_int {
    guard("ihs_wl_view_capabilities", || {
        if capabilities & !CAPABILITY_ALL != 0 {
            return Err(Error::invalid(format!(
                "bad capabilities {capabilities:#x}"
            )));
        }
        thread::send(thread::Cmd::ViewCapabilities {
            view_id,
            capabilities,
        })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// The window states the app grants the toplevel the view `view_id` shows,
/// as `IhsWlWindowState` bits, typically in answer to its client's requests.
/// Its size stays the view's either way. Any thread; only enqueues.
#[no_mangle]
pub extern "C" fn ihs_wl_view_state(view_id: i32, state: u32) -> c_int {
    guard("ihs_wl_view_state", || {
        if state & !WINDOW_STATE_ALL != 0 {
            return Err(Error::invalid(format!("bad window state {state:#x}")));
        }
        thread::send(thread::Cmd::ViewState { view_id, state })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// Post view events (`IhsWlViewEvent`, `[event, view_id]`) and window events
/// (`IhsWlToplevelEvent`, `[event, toplevel_id]`) from now on to the Dart
/// native port `port` with `post`, which is `NativeApi.postCObject`. NULL
/// `post` stops. A port whose isolate is gone only drops them, so after a
/// hot restart the new isolate registers its own. Any thread.
#[no_mangle]
pub extern "C" fn ihs_wl_set_event_port(
    post: Option<unsafe extern "C" fn(port: i64, message: *mut std::ffi::c_void) -> bool>,
    port: i64,
) -> c_int {
    guard("ihs_wl_set_event_port", || {
        events::set_sink(post.map(|p| (p, port)));
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// Ask the client of the view `view_id` for `width` x `height` logical
/// pixels instead of the view's size; its content is scaled to fit the view,
/// aspect kept, centered, and input is mapped back. 0 x 0 goes back to the
/// view's size. Any thread; only enqueues.
#[no_mangle]
pub extern "C" fn ihs_wl_view_size(view_id: i32, width: f64, height: f64) -> c_int {
    guard("ihs_wl_view_size", || {
        if !(width.is_finite() && height.is_finite() && width >= 0.0 && height >= 0.0)
            || ((width == 0.0) != (height == 0.0))
        {
            return Err(Error::invalid(format!("bad view size {width} x {height}")));
        }
        thread::send(thread::Cmd::ViewRequestSize {
            view_id,
            size: requested_size(width, height),
        })?;
        Ok(IhsWlResult::Ok as c_int)
    })
}

/// A requested client size in whole logical pixels: None unless both sides
/// are positive.
pub(crate) fn requested_size(width: f64, height: f64) -> Option<(i32, i32)> {
    let side = |v: f64| (v.round() as i32).max(1);
    (width > 0.0 && height > 0.0).then(|| (side(width), side(height)))
}

/// The message for the last failed call on this thread; never NULL, empty
/// when there has been none. Valid until the next call on this thread.
#[no_mangle]
pub extern "C" fn ihs_wl_last_error() -> *const c_char {
    LAST_ERROR.with(|e| e.borrow().as_ptr())
}

/// Rust entry points, for tests and Rust embedders.
pub fn start(config: Config) -> Result<()> {
    thread::start(config)
}

pub fn stop() -> Result<()> {
    thread::stop()
}

pub fn socket_name() -> Option<String> {
    thread::socket_name()
}

/// Who the client of the toplevel the view @p view_id shows is; None while
/// it shows none.
pub fn view_client(view_id: i32) -> Result<Option<ClientInfo>> {
    let (tx, rx) = std::sync::mpsc::sync_channel(1);
    thread::send(thread::Cmd::ViewClient { view_id, reply: tx })?;
    rx.recv_timeout(std::time::Duration::from_secs(2))
        .map_err(|e| Error::new(IhsWlResult::ErrInternal as i32, format!("no reply: {e}")))
}

/// The window @p toplevel_id; None once it is gone.
pub fn toplevel_info(toplevel_id: i64) -> Result<Option<ToplevelInfo>> {
    let (tx, rx) = std::sync::mpsc::sync_channel(1);
    thread::send(thread::Cmd::ToplevelInfo {
        toplevel_id,
        reply: tx,
    })?;
    rx.recv_timeout(std::time::Duration::from_secs(2))
        .map_err(|e| Error::new(IhsWlResult::ErrInternal as i32, format!("no reply: {e}")))
}

/// The windows there are now, oldest first.
pub fn toplevels() -> Result<Vec<i64>> {
    let (tx, rx) = std::sync::mpsc::sync_channel(1);
    thread::send(thread::Cmd::Toplevels(tx))?;
    rx.recv_timeout(std::time::Duration::from_secs(2))
        .map_err(|e| Error::new(IhsWlResult::ErrInternal as i32, format!("no reply: {e}")))
}

#[cfg(test)]
mod tests {
    use super::copy_str;
    use std::ffi::CStr;

    #[test]
    fn copy_str_cuts_at_a_character_boundary() {
        let mut out = [0; 256];
        let copied = |out: &[std::ffi::c_char; 256]| {
            unsafe { CStr::from_ptr(out.as_ptr()) }
                .to_str()
                .unwrap()
                .to_owned()
        };
        // 254 bytes, then a 2-byte character that would end at byte 256.
        let s = format!("{}é", "a".repeat(254));
        copy_str(&mut out, Some(&s));
        assert_eq!(copied(&out), "a".repeat(254), "cut before the character");
        copy_str(&mut out, Some("é"));
        assert_eq!(copied(&out), "é");
        copy_str(&mut out, None);
        assert_eq!(copied(&out), "");
    }
}
